package dz.local.mealguard;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import org.robolectric.shadows.ShadowAlertDialog;import android.app.AlertDialog;import android.view.*;import android.widget.*;import org.json.*;import java.lang.reflect.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,35})
public class WeeklyActivityTest {
 View find(View v,String s){if(v instanceof TextView&&((TextView)v).getText().toString().equals(s))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),s);if(f!=null)return f;}return null;}
 void invoke(MainActivity a,String name,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(a,args);}
 void field(MainActivity a,String name,Object value)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(a,value);}
 void spinners(View v,List<ChoiceField> list){if(v instanceof ChoiceField)list.add((ChoiceField)v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)spinners(((ViewGroup)v).getChildAt(i),list);}
 @Test public void freshAccountCannotConfigureRulesBeforeDefaults(){try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){View root=c.get().getWindow().getDecorView();find(root,"الإعدادات").performClick();find(root,"الاستثناءات الأسبوعية").performClick();assertTrue(find(root,"تسجيل الدخول والمتابعة").isShown());assertFalse(new Vault(c.get()).enabled());}}
 @Test public void sevenDayPickerAndThreeMealEditorsPreserveSavedChoiceOnCancel()throws Exception{Vault vault=new Vault(RuntimeEnvironment.getApplication());vault.clear();try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();JSONObject cfg=new JSONObject().put("breakfast_id",10).put("lunch_id",20).put("dinner_id",10);JSONArray depots=new JSONArray();for(int id:new int[]{10,20,30})depots.put(new JSONObject().put("id",id).put("nameFR","R"+id).put("breakfast",true).put("lunch",true).put("dinner",true));JSONObject[] chosen=new JSONObject[4];chosen[2]=depots.getJSONObject(2);cfg=WeeklySchedule.setDay(cfg,5,chosen,depots);field(a,"cfg",cfg);field(a,"depots",depots);invoke(a,"update",new Class<?>[]{});for(int day=1;day<=7;day++)assertNotNull(WeeklySchedule.DAYS[day],find(a.getWindow().getDecorView(),WeeklySchedule.DAYS[day]));invoke(a,"weeklyDay",new Class<?>[]{int.class},5);AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();List<ChoiceField> list=new ArrayList<>();spinners(d.getWindow().getDecorView(),list);assertEquals(3,list.size());assertEquals(0,list.get(0).getSelectedItemPosition());assertEquals(4,list.get(1).getSelectedItemPosition());list.get(1).setSelection(0);d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();assertEquals(30,WeeklySchedule.restaurant(cfg,5,2));assertFalse(vault.enabled());}finally{vault.clear();}}
 private void textsOf(View v,List<String> out){if(v instanceof TextView){String t=((TextView)v).getText().toString();if(!t.isEmpty())out.add(t);}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)textsOf(((ViewGroup)v).getChildAt(i),out);}
 private JSONObject cfgOf(MainActivity a)throws Exception{Field f=MainActivity.class.getDeclaredField("cfg");f.setAccessible(true);return (JSONObject)f.get(a);}
 @Test public void weeklySkipOptionIsOfferedForConfiguredMealsAndRestoredWhenSaved()throws Exception{Vault vault=new Vault(RuntimeEnvironment.getApplication());vault.clear();try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();JSONObject cfg=new JSONObject().put("breakfast_id",10).put("lunch_id",20).put("dinner_id",10);JSONArray depots=new JSONArray();for(int id:new int[]{10,20,30})depots.put(new JSONObject().put("id",id).put("nameFR","R"+id).put("breakfast",true).put("lunch",true).put("dinner",true));field(a,"cfg",cfg);field(a,"depots",depots);invoke(a,"update",new Class<?>[]{});invoke(a,"weeklyDay",new Class<?>[]{int.class},5);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();List<ChoiceField> list=new ArrayList<>();spinners(d.getWindow().getDecorView(),list);assertEquals(3,list.size());for(int i=0;i<3;i++)assertEquals(5,list.get(i).getCount());Field fi=ChoiceField.class.getDeclaredField("items");fi.setAccessible(true);for(ChoiceField sp:list){List<?> names=(List<?>)fi.get(sp);assertEquals("تخطي هذه الوجبة",String.valueOf(names.get(1)));assertEquals(0,sp.getSelectedItemPosition());}d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();// fresh state: usual offered, nothing saved yet
 JSONObject withSkip=WeeklySchedule.setDay(cfg,5,new JSONObject[]{null,null,new JSONObject().put("skip",true),null},depots);field(a,"cfg",withSkip);invoke(a,"weeklyDay",new Class<?>[]{int.class},5);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();d=ShadowAlertDialog.getLatestAlertDialog();list=new ArrayList<>();spinners(d.getWindow().getDecorView(),list);assertEquals(1,list.get(1).getSelectedItemPosition());d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();}finally{vault.clear();}}
 @Test public void weeklyDialogOffersFullMenuForUnconfiguredBaseMeal()throws Exception{Vault vault=new Vault(RuntimeEnvironment.getApplication());vault.clear();try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();JSONObject cfg=new JSONObject().put("lunch_id",20);JSONArray depots=new JSONArray();for(int id:new int[]{10,20,30})depots.put(new JSONObject().put("id",id).put("nameFR","R"+id).put("breakfast",true).put("lunch",true).put("dinner",true));field(a,"cfg",cfg);field(a,"depots",depots);invoke(a,"update",new Class<?>[]{});invoke(a,"weeklyDay",new Class<?>[]{int.class},3);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();List<ChoiceField> list=new ArrayList<>();spinners(d.getWindow().getDecorView(),list);assertEquals(3,list.size());Field fi=ChoiceField.class.getDeclaredField("items");fi.setAccessible(true);List<?> b=(List<?>)fi.get(list.get(0)),l=(List<?>)fi.get(list.get(1)),e=(List<?>)fi.get(list.get(2));assertEquals(4,b.size());assertEquals("غير مُختارة",String.valueOf(b.get(0)));assertEquals("R10",String.valueOf(b.get(1)));assertEquals(5,l.size());assertEquals(4,e.size());assertEquals("غير مُختارة",String.valueOf(e.get(0)));assertEquals("R10",String.valueOf(e.get(1)));assertEquals(0,list.get(0).getSelectedItemPosition());assertEquals(0,list.get(2).getSelectedItemPosition());d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();
 JSONObject withException=WeeklySchedule.setDay(cfg,3,new JSONObject[]{null,new JSONObject().put("id",30).put("name","R30"),null,null},depots);field(a,"cfg",withException);invoke(a,"weeklyDay",new Class<?>[]{int.class},3);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();d=ShadowAlertDialog.getLatestAlertDialog();list=new ArrayList<>();spinners(d.getWindow().getDecorView(),list);assertEquals(3,list.get(0).getSelectedItemPosition());d.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();}finally{vault.clear();}}
 @Test public void reviewListsActualRestaurantForEachMeal()throws Exception{try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();JSONObject depot=new JSONObject().put("id",99).put("nameFR","Friday alternative");List<Engine.Meal> one=Collections.singletonList(new Engine.Meal(java.time.LocalDate.of(2026,11,6),2,depot,0));Method mi=MainActivity.class.getDeclaredMethod("planItems",List.class,List.class);mi.setAccessible(true);JSONArray items=(JSONArray)mi.invoke(a,one,Collections.emptyList());LinearLayout box=new LinearLayout(a);invoke(a,"renderPlan",new Class<?>[]{LinearLayout.class,JSONArray.class,java.time.LocalDate.class},box,items,null);assertNotNull(find(box,"Friday alternative"));assertNotNull(find(box,"الغداء"));}}
}
